static int test_omp_api()
{
    if (!(omp_get_num_procs() >= 1))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "omp_get_num_procs() >= 1");
        return -1;
    }
    if (!(omp_get_thread_limit() >= 1))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "omp_get_thread_limit() >= 1");
        return -1;
    }
    if (!(omp_in_parallel() == 0))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "omp_in_parallel() == 0");
        return -1;
    }
    if (!(omp_get_level() == 0))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "omp_get_level() == 0");
        return -1;
    }
    if (!(omp_get_active_level() == 0))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "omp_get_active_level() == 0");
        return -1;
    }

    int inpar = 0;
    int level = -1;
    int active = -1;
    #pragma omp parallel num_threads(4)
    {
        if (omp_get_thread_num() == 0)
        {
            inpar = omp_in_parallel();
            level = omp_get_level();
            active = omp_get_active_level();
        }
    }
    if (!(inpar == 1))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "inpar == 1");
        return -1;
    }
    if (!(level == 1))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "level == 1");
        return -1;
    }
    if (!(active == 1))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "active == 1");
        return -1;
    }

    int dyn = omp_get_dynamic();
    if (!(dyn == 0 || dyn == 1))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "dyn == 0 || dyn == 1");
        return -1;
    }
    omp_set_dynamic(0);
    omp_set_dynamic(1);

    return 0;
}

