static int test_barrier_twice()
{
    int seen[64];
    int total = 0;
    int bad = 0;
    for (int i = 0; i < 64; i++) seen[i] = 0;

    #pragma omp parallel num_threads(4)
    {
        int nt = omp_get_num_threads();
        int tid = omp_get_thread_num();

        seen[tid] = 1;
        #pragma omp barrier
        // all writes before the first barrier must be visible here
        for (int i = 0; i < nt; i++)
            if (seen[i] != 1) bad = 1;

        #pragma omp atomic
        total++;

        #pragma omp barrier
        // no further increment happens after the second barrier
        if (total != nt) bad = 1;
    }

    if (!(bad == 0))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "bad == 0");
        return -1;
    }
    if (!(total >= 1 && total <= 4))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "total >= 1 && total <= 4");
        return -1;
    }

    return 0;
}

