static int test_num_threads()
{
    int team = 0;
    omp_set_num_threads(2);
    #pragma omp parallel
    {
        if (omp_get_thread_num() == 0) team = omp_get_num_threads();
    }
    if (!(team >= 1 && team <= 2))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "team >= 1 && team <= 2");
        return -1;
    }

    omp_set_num_threads(4);
    team = 0;
    int seen[64];
    for (int i = 0; i < 64; i++) seen[i] = 0;
    #pragma omp parallel num_threads(4)
    {
        int tid = omp_get_thread_num();
        if (tid == 0) team = omp_get_num_threads();
        if (tid < 64) seen[tid] = 1;
    }
    if (!(team >= 1 && team <= 4))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "team >= 1 && team <= 4");
        return -1;
    }
    int cnt = 0;
    for (int i = 0; i < 64; i++) cnt += seen[i];
    if (!(cnt == team))
    {
        fprintf(stderr, "test_simpleomp %s failed: %s\n", __func__, "cnt == team");
        return -1;
    }

    return 0;
}

