static int test_ordered_guided_runtime()
{
    const int n = 1003;
    int order[1003];
    int next = 0;
    for (int i = 0; i < n; i++) order[i] = -1;

    #pragma omp parallel for ordered schedule(guided)
    for (int i = 0; i < n; i++)
    {
        #pragma omp ordered
        {
            if (next < n) order[next] = i;
            next++;
        }
    }

    int bad = 0;
    for (int i = 0; i < n; i++) if (order[i] != i) bad++;
    if (next != n) bad = 1;

    for (int i = 0; i < n; i++) order[i] = -1;
    next = 0;
    #pragma omp parallel for ordered schedule(runtime)
    for (int i = 0; i < n; i++)
    {
        #pragma omp ordered
        {
            if (next < n) order[next] = i;
            next++;
        }
    }
    for (int i = 0; i < n; i++) if (order[i] != i) bad++;
    if (next != n) bad = 1;

    if (bad) { fprintf(stderr, "test_simpleomp %s failed\n", __func__); return -1; }
    return 0;
}

