static int test_copyprivate()
{
    int results[8];
    int team_size = 0;
    for (int i = 0; i < 8; i++) results[i] = 0;

    #pragma omp parallel num_threads(4)
    {
        int y = 0;
        #pragma omp single copyprivate(y)
        {
            y = 42;
            team_size = omp_get_num_threads();
        }
        results[omp_get_thread_num()] = y;
    }

    int bad = team_size < 1 ? 1 : 0;
    for (int i = 0; i < team_size && i < 8; i++) if (results[i] != 42) bad++;
    if (bad) { fprintf(stderr, "test_simpleomp %s failed\n", __func__); return -1; }
    return 0;
}

static int test_nested_serialized_dispatch()
{
    const int n = 64;
    int order[64];
    int next = 0;
    for (int i = 0; i < n; i++) order[i] = -1;

    #pragma omp parallel for ordered schedule(dynamic, 1)
    for (int i = 0; i < n; i++)
    {
        #pragma omp parallel if(0)
        {
            #pragma omp for schedule(dynamic, 1)
            for (int j = 0; j < 8; j++)
            {
                volatile int sink = j;
                (void)sink;
            }
        }

        #pragma omp ordered
        {
            if (next < n) order[next] = i;
            next++;
        }
    }

    int bad = 0;
    if (next != n) bad = 1;
    for (int i = 0; i < n; i++) if (order[i] != i) bad++;
    if (bad) { fprintf(stderr, "test_simpleomp %s failed next=%d\n", __func__, next); return -1; }
    return 0;
}

