static int test_nested_static_claim()
{
    const int n = 64;
    int order[64];
    int next = 0;
    for (int i = 0; i < n; i++) order[i] = -1;

    #pragma omp parallel for ordered schedule(static, 1)
    for (int i = 0; i < n; i++)
    {
        #pragma omp parallel if(0)
        {
            #pragma omp for schedule(static, 1)
            for (int j = 0; j < 8; j++)
            {
                volatile int sink = j;
                (void)sink;
            }
        }

        GOMP_parallel_start(gomp_empty_split_body, 0, 1);
        gomp_empty_split_body(0);
        GOMP_parallel_end();

        #pragma omp ordered
        {
            if (next < n) order[next] = i;
            next++;
        }
    }

    int bad = 0;
    if (next != n) bad = 1;
    for (int i = 0; i < n; i++) if (order[i] != i) bad++;
    if (bad) { fprintf(stderr, "test_simpleomp %s failed next=%d\n", __func__, next); return -1; }
    return 0;
}
