#if defined(__clang__)
static int test_conditional_ordered()
{
    const int n = 101;
    int order[101];
    int next = 0;
    for (int i = 0; i < 101; i++) order[i] = -1;

    #pragma omp parallel for ordered schedule(dynamic, 2)
    for (int i = 0; i < n; i++)
    {
        if (i % 2)
        {
            #pragma omp ordered
            {
                if (next < n) order[next] = i;
                next++;
            }
        }
    }

    int expect = n / 2;
    int bad = next != expect ? 1 : 0;
    for (int k = 0; k < expect; k++) if (order[k] != 2 * k + 1) bad++;
    if (bad) { fprintf(stderr, "test_simpleomp %s failed next=%d\n", __func__, next); return -1; }
    return 0;
}
#endif

